INSERT INTO public.knowledge_content (company_id, module, module_title, concepto, enseñanza, ejemplo, pregunta, opciones, respuesta, orden) SELECT 'ef4e8f32-fa7d-489b-894e-5a39b9ea994c', 'grupo-4-invu', 'Hardware INVU', concepto, enseñanza, ejemplo, NULL, NULL, NULL, orden FROM (VALUES ('Soporte Local 24/7 – El Seguro de Continuidad para el Cliente', 'INVU tiene equipo de soporte en Perú, con WhatsApp directo a un humano, soporte remoto y en sitio. La competencia tiene tickets de 24-48 horas y soporte desde otro país. Cuando el sistema falla un viernes a las 9pm, el cliente llama a un equipo en Perú que responde en minutos. El Hunter debe vender esto como tranquilidad operativa. Es un argumento que la competencia no puede igualar.', 'Un cliente objeta: "¿Y si el sistema falla un viernes a las 9pm?" El Hunter responde: "Excelente pregunta. Con INVU, llamas a nuestro equipo en Perú, por WhatsApp, y te responde un humano. No bots, no formularios, no espera de 48 horas. La competencia te da un ticket que responden en 24-48 horas desde otro país. INVU te da un humano que habla tu idioma." El cliente se siente seguro.', 16),
('Ecosistema Móvil Nativo – El Negocio en el Bolsillo del Dueño', 'INVU ofrece tres apps nativas: POS para operar, Reports para medir desde cualquier lugar, y Supply para inventario y compras desde el móvil. La competencia encadena al usuario a una sola pantalla fija. El Hunter debe comunicar que INVU libera al dueño de la obligación de estar presente para controlar su negocio. Es el sueño del emprendedor: control total desde la palma de la mano.', '"Con INVU, tu negocio vive donde vos estés. Operás desde cualquier dispositivo con INVU POS, medís tus ventas y movimientos con INVU Reports desde tu celular, y gestionás compras e inventario con INVU Supply. No estás encadenado a una caja fija. Puedes estar en casa o de viaje y saber exactamente cómo va tu operación."', 17),
('Ecosistema Integrado sin Comisiones – El 100% es para Ti', 'INVU integra POS, KDS, inventario, QR, kioskos, loyalty y e-commerce en una sola plataforma, con e-commerce propio sin comisiones por venta. La competencia cobra comisiones de 25-30% por delivery. El Hunter debe mostrar que INVU permite vender sin ceder margen a terceros, lo que multiplica la rentabilidad del cliente. Es una propuesta de valor que la competencia no puede ofrecer.', '"No necesitas cinco sistemas diferentes. INVU integra POS, inventario, facturación, QR, kioskos, loyalty y e-commerce en una sola plataforma. Y tu tienda online no paga comisiones: el 100% de la venta es para ti. Un solo sistema, un solo costo, cero comisiones. Lo que antes perdías en Rappi, ahora lo ganas."', 18),
('El KPI del Hunter – De Discovery a Cotización', 'El KPI principal del Hunter no es cuántas demos se hacen, sino cuántos clientes pasan de discovery a cotización. Ahí está la conversión real. El Hunter debe enfocar sus esfuerzos en calificar oportunidades y avanzarlas en el pipeline. Una demo sin cotización es una oportunidad perdida. El objetivo es convertir cada oportunidad calificada en una cotización y cada cotización en un cierre.', 'Un Hunter hace 5 demos al mes, pero solo convierte 2 en cotizaciones. Su tasa de conversión es del 40%. Otro Hunter hace 5 demos y convierte 4 en cotizaciones (80%). Su ingreso es el doble. El KPI es la conversión, no la actividad. El Hunter debe enfocarse en calificar mejor y avanzar más rápido las oportunidades.


# PÍLDORAS DE CONOCIMIENTO - HARDWARE Y PROCESO DE VISITA TÉCNICA INVU POS', 19),
('La Visita Técnica – No es un Trámite, es una Herramienta de Ventas', 'La visita técnica en INVU POS no es un simple trámite de instalación. Es una herramienta estratégica de consultoría que se sitúa entre la validación comercial inicial y la cotización definitiva, permitiendo al Hunter demostrar profesionalismo, identificar necesidades adicionales de hardware y garantizar una implementación exitosa desde el día uno. El Hunter que entiende esto no ve la visita como una obligación, sino como una oportunidad de cerrar con autoridad.', 'Un Hunter ha cerrado la demo y el cliente está interesado, pero duda por el precio. El Hunter dice: "Antes de darte la cotización definitiva, nuestro especialista técnico va a evaluar tu local sin costo. Te va a decir qué hardware puedes reutilizar y qué necesitas para que tu operación funcione sin interrupciones. Con ese informe, te doy una cotización precisa y te aseguro que desde el día uno estarás operando." El cliente, que ve profesionalismo, acepta la visita y el Hunter usa el informe para cerrar.', 20),
('La Visita Técnica como Auditoría Operativa Integral', 'La visita técnica es una auditoría operativa integral que evalúa tres dimensiones críticas: conectividad (velocidad de internet, estabilidad del enlace, cobertura WiFi), equipamiento (impresoras, balanzas, cajones, lectores), y red de trabajo (topologías de red local, ruteo de cables, ubicación de estaciones). No es una inspección superficial; es una evaluación profunda que garantiza que el sistema funcionará desde el día uno.', 'El especialista de INVU llega al local del cliente. No solo mira la impresora; la prueba, mide la velocidad del internet, camina por todo el local con un medidor de WiFi, revisa los cables, y evalúa dónde debería ir la caja y la pantalla KDS. Al final, entrega un informe detallado. El cliente queda impresionado porque nunca nadie había hecho una evaluación tan completa. La confianza en INVU se multiplica.', 21),
('La Visita Técnica – Consultoría Gratuita, no Inspección de Control', 'INVU no envía a un técnico a revisar si el cliente cumple requisitos para negarle el servicio. Envía un especialista para asegurar que la implementación sea 100% exitosa y para hacer recomendaciones personalizadas según el flujo de operación del negocio. El Hunter debe comunicar esto como un valor agregado, no como una inspección.', 'Un cliente dice: "¿Van a venir a revisar mi local para ver si cumplo con requisitos?" El Hunter responde: "No es una inspección. Es una consultoría gratuita. Nuestro especialista viene a asegurarse de que tu implementación sea exitosa. Te va a recomendar qué hardware puedes reutilizar y qué mejoras te van a ayudar a operar sin problemas. No es para negarte el servicio; es para que funcione perfectamente desde el día uno."', 22),
('Reutilización de Hardware – Confianza y Ahorro para el Cliente', 'A diferencia de muchos POS que obligan al cliente a comprar todo el hardware nuevo, INVU evalúa lo que el cliente ya tiene y recomienda reutilizar todo lo que sea compatible (impresoras, lectores, cajones). Esto ahorra dinero al cliente y construye confianza. El Hunter debe comunicar esto como un gesto de honestidad, no como una concesión.', 'El cliente dice: "No quiero comprar impresoras nuevas." El Hunter responde: "No vamos a obligarte a comprar hardware nuevo si lo que tienes funciona. Nuestro especialista va a revisar tus impresoras, lectores y cajones, y te va a recomendar reutilizar todo lo que sea compatible. Así ahorras en la inversión inicial y solo compras lo que realmente necesitas." El cliente confía en el vendedor porque no le está vendiendo algo que no necesita.', 23),
('La Evaluación de Conectividad – El Combustible del Sistema', 'El internet es el combustible de INVU POS. Si la red falla, el sistema no opera, las ventas se pierden y el cliente se frustra. El especialista técnico evalúa la velocidad del internet contratado, la estabilidad del enlace de datos, y mapea la cobertura WiFi del recinto comercial, identificando puntos muertos. El Hunter debe comunicar que esta evaluación es esencial para la continuidad del negocio.', '"La velocidad es solo una parte. También evaluamos la estabilidad, la latencia, y la cobertura WiFi en toda el área del local. A veces el internet es rápido pero la señal no llega a la cocina, o se cae en horas pico. Nuestro especialista va a medir todo eso para asegurarse de que no tengas puntos ciegos." El cliente, que ha tenido caídas en horas pico, valora la evaluación.', 24),
('Fibra Óptica vs. Coaxial – La Diferencia que Afecta la Operación', 'INVU recomienda fibra óptica (FTTH) para estabilidad y baja latencia. Coaxial (HFC) genera latencia inestable y no es recomendado para operaciones de alta demanda. El Hunter debe saber esto para recomendar la mejora si el cliente tiene coaxial. Esta recomendación puede evitar problemas críticos en la operación.', 'Durante la visita, el especialista detecta que el cliente tiene internet coaxial. Le explica: "El coaxial es inestable y puede generar latencia en horas pico, lo que afectaría tu sistema y tus integraciones con delivery. Te recomendamos migrar a fibra óptica para garantizar estabilidad. Es una inversión que te ahorrará dolores de cabeza." El cliente, que no sabía la diferencia, valora la recomendación profesional.', 25),
('El Router 4G/5G de Respaldo – El Seguro de Continuidad', 'Para comercios con alta demanda de delivery e integraciones, INVU recomienda instalar un router con chip 4G/5G de contingencia automática que asegura operación continua si el internet principal falla. El Hunter debe vender esto como un seguro, no como un lujo. Es la garantía de que el negocio nunca se detiene.', '"Tu internet puede fallar, pero tu negocio no debe detenerse. Por eso recomendamos un router con chip 4G de respaldo. Si el internet principal se cae, el sistema cambia automáticamente al respaldo y sigues operando sin perder una venta. Es tu seguro de continuidad." El cliente, que ha perdido ventas por cortes de internet, ve el valor inmediato y acepta la recomendación.', 26),
('El Hardware Homologado – Impresora 3nStar RPT004', 'INVU recomienda la impresora 3nStar RPT004 como hardware oficial por su altísima resistencia térmica y doble interfaz (USB/LAN), garantizando durabilidad y compatibilidad. Una impresora que se traba genera caos en la operación. El Hunter debe comunicar que el hardware homologado es una inversión en estabilidad, no un gasto.', '"Recomendamos la impresora 3nStar RPT004 porque es la que hemos probado y validado para funcionar perfectamente con INVU. Es resistente, rápida y tiene doble conexión USB/LAN, así que no se desconecta. Es una inversión que te ahorrará dolores de cabeza a largo plazo." El cliente, que ha sufrido con impresoras que se traban, aprecia la recomendación.', 27),
('Evaluación de Topología de Red – La Eficiencia Operativa', 'INVU no solo instala el software en cualquier lugar. Diseña la distribución de los equipos para maximizar la eficiencia operativa: dónde va la caja, dónde va la impresora de comandas, dónde va la pantalla KDS en cocina. Una mala ubicación genera cuellos de botella. El Hunter debe comunicar que la visita técnica optimiza el flujo de trabajo.', '"No solo instalamos el sistema en cualquier lugar. Nuestro especialista diseña la ubicación de cada equipo para que tu operación sea lo más eficiente posible: la caja en el lugar correcto, la impresora de comandas donde la cocina la vea rápido, la pantalla KDS donde el cocinero la tenga a la vista. Así tu personal trabaja más rápido y tus clientes esperan menos."', 28),
('El Sistema Mesh WiFi – El Fin de los Puntos Muertos', 'Cuando la cobertura WiFi no llega a toda el área del local (especialmente a la cocina o al fondo del restaurante), el especialista recomienda sistemas de red en malla (Mesh WiFi) para eliminar puntos muertos. El Hunter debe comunicar que esto garantiza que el sistema funcione en todo el local, sin interrupciones.', 'Durante la visita, el especialista detecta que la señal WiFi no llega a la cocina. Le dice al dueño: "Tu cocina está en un punto muerto. Los pedidos pueden no llegar a tiempo. Te recomendamos un sistema Mesh WiFi para que la señal llegue a todo el local. Es una inversión pequeña que garantiza que tu operación fluya sin interrupciones."', 29),
('El Upselling durante la Visita Técnica – +40% de Ticket Promedio', 'Según datos históricos de INVU, la visita técnica genera un +40% de aumento en el ticket medio al identificar necesidades adicionales de hardware que el cliente no había considerado: tablets nuevas, impresoras adicionales, routers mejorados, sistemas Mesh, hardware de respaldo. El Hunter que domina la visita técnica convierte cada visita en una oportunidad de upselling.', 'Un Hunter agenda la visita técnica para un restaurante. El especialista descubre que el WiFi no llega a la cocina, que la impresora es obsoleta, y que el internet es coaxial. El informe recomienda: router Mesh WiFi, impresora 3nStar RPT004, y migración a fibra óptica. El Hunter incluye esto en la cotización, sumando S/1,500 en hardware adicional. Su comisión (10% desde la 4ª venta) aumenta en S/150. El cliente tiene certeza de que el sistema funcionará sin problemas.', 30)) AS t(concepto, enseñanza, ejemplo, orden);